function dashboardView() {
  const completed=state.sessions.filter((session)=>(session.responses??[]).length>0);const latest=completed.at(-1);const assessmentSessions=completed.filter((session)=>session.mode==="assessment");const latestAssessment=assessmentSessions.at(-1);const metrics=latestAssessment?calculateMetrics(latestAssessment.responses.filter((response)=>response.phase==="post")):latest?calculateMetrics(latest.responses):null;const allResponses=completed.flatMap((session)=>session.responses??[]);const blindSpots=computeBlindSpots(allResponses);
  return shell(`<section class="page-heading page-heading--row"><div><button class="back-button" data-route="home">← 回首頁</button><p>本機學習紀錄</p><h1>我的判斷盲點</h1><span>只顯示這台裝置上的匿名紀錄。</span></div><button class="button button--secondary" data-route="data">資料與隱私</button></section>${metrics?`<section class="dashboard-grid"><article class="score-card score-card--primary"><p>安全行動正確率</p><strong>${formatPercent(metrics.actionAccuracy)}</strong><span>是否先停止高風險操作並改走查證</span></article>${latestAssessment?`<article class="score-card"><p>三分類校準</p><strong>${formatPercent(metrics.judgmentMacroRecall)}</strong><span>三類 recall 的平均，不讓全選可疑得高分</span></article><article class="score-card"><p>較可信誤判率</p><strong>${formatPercent(metrics.trustedFalsePositiveRate)}</strong><span>把較可信訊息誤判為明顯風險</span></article>`:`<article class="score-card"><p>關鍵訊號 F1</p><strong>${formatPercent(metrics.signalF1)}</strong><span>是否選到真正重要的線索</span></article><article class="score-card"><p>中位作答時間</p><strong>${Math.round(metrics.medianResponseTimeMs/1000)} 秒</strong><span>速度不計分，只用來觀察流程負擔</span></article>`}<article class="score-card"><p>${latestAssessment?"關鍵訊號 F1":"已完成練習"}</p><strong>${latestAssessment?formatPercent(metrics.signalF1):`${completed.length} 次`}</strong><span>${latestAssessment?"是否選到真正重要的線索":"完整測驗後才會顯示三分類校準"}</span></article></section><section class="dashboard-detail">${latestAssessment?`<article class="calibration-card"><div class="section-heading"><div><p>分類細節</p><h2>不要只會全部選可疑</h2></div><span>最近一次後測</span></div>${metricBar("有明顯風險",metrics.recallRisk,"risk")}${metricBar("資訊不足",metrics.recallInsufficient,"insufficient")}${metricBar("目前較可信",metrics.recallTrusted,"trusted")}<div class="calibration-footer"><span>高自信錯誤 ${formatPercent(metrics.highConfidenceErrorRate)}</span><span>中位作答 ${Math.round(metrics.medianResponseTimeMs/1000)} 秒</span></div></article>`:`<article class="calibration-card"><div class="section-heading"><div><p>快練說明</p><h2>日常模式不測真假分類</h2></div><span>最近一次快練</span></div><div class="quick-insight"><span>${icon("shield",28)}</span><div><strong>先做對下一步</strong><p>90 秒快練只記錄安全行動與一個關鍵訊號。完成完整能力測驗後，才會顯示三分類校準、較可信誤判率與高自信錯誤。</p></div></div><div class="calibration-footer"><span>關鍵訊號 ${formatPercent(metrics.signalF1)}</span><span>中位作答 ${Math.round(metrics.medianResponseTimeMs/1000)} 秒</span></div></article>`}<article class="blind-spot-card"><div class="section-heading"><div><p>個人盲點</p><h2>最常漏看的訊號</h2></div></div>${blindSpots.length?blindSpots.map((item,index)=>`<div class="blind-item"><span>${String(index+1).padStart(2,"0")}</span><div><strong>${item.label}</strong><small>漏選 ${item.count} 次</small></div></div>`).join(""):`<div class="empty-state">目前沒有足夠資料。再完成幾次快練後會顯示。</div>`}</article></section>`:`<section class="empty-dashboard"><span>${icon("chart",44)}</span><h2>還沒有學習紀錄</h2><p>完成一次 90 秒快練或完整測驗後，這裡會顯示你的安全行動與判斷盲點。</p><button class="button button--primary" data-action="start-quick">開始 90 秒快練</button></section>`}<section class="history-section"><div class="section-heading"><div><p>最近紀錄</p><h2>這台裝置上的練習</h2></div><span>${completed.length} 次</span></div><div class="history-list">${completed.length?completed.toReversed().slice(0,6).map((session)=>{const sessionMetrics=calculateMetrics(session.responses);return `<article><span class="history-icon">${icon(session.mode==="quick"?"bolt":"brain",21)}</span><div><strong>${session.mode==="quick"?"90 秒快練":"完整能力測驗"}</strong><small>${new Date(session.completedAt).toLocaleString("zh-TW",{month:"numeric",day:"numeric",hour:"2-digit",minute:"2-digit"})}</small></div><div class="history-metric"><strong>${formatPercent(sessionMetrics.actionAccuracy)}</strong><small>安全行動</small></div></article>`;}).join(""):""}</div></section>`);
}
function metricBar(label,value,className){const percent=Math.round(value*100);return `<div class="metric-bar"><div><span>${label}</span><strong>${formatPercent(value)}</strong></div><div class="metric-bar__track" role="progressbar" aria-label="${label}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${percent}"><span class="metric-bar__fill metric-bar__fill--${className}" style="width:${percent}%"></span></div></div>`;}
function computeBlindSpots(responses){const counts=new Map();for(const response of responses){for(const signalId of response.correctSignalIds??[]){if(!(response.selectedSignalIds??[]).includes(signalId)){const question=getQuestionById(response.questionId);const label=question?.signalOptions.find((item)=>item.id===signalId)?.label??signalId;counts.set(label,(counts.get(label)??0)+1);}}}return [...counts.entries()].map(([label,count])=>({label,count})).toSorted((a,b)=>b.count-a.count).slice(0,4);}
function emergencyView(){const emergency=currentFlow?.type==="emergency"?currentFlow:{type:"emergency",step:1,answers:{}};currentFlow=emergency;return shell(`<section class="page-heading"><button class="back-button" data-route="home">← 回首頁</button><p>事件當下輔助</p><h1>先停手，再查證。</h1><span>不要貼上訊息、截圖、帳號、密碼或 OTP。SignalSafe 不替你判定真假。</span></section><section class="emergency-shell"><div class="emergency-progress"><span class="${emergency.step>=1?"is-active":""}">1</span><i></i><span class="${emergency.step>=2?"is-active":""}">2</span><i></i><span class="${emergency.step>=3?"is-active":""}">3</span></div>${emergency.step===1?emergencyStepOne(emergency):emergency.step===2?emergencyStepTwo(emergency):emergencyResult(emergency)}</section>`);}
function emergencyStepOne(emergency){const options=[["login","點連結或登入帳號"],["payment","付款、轉帳或操作 ATM"],["otp","提供驗證碼、密碼或卡片資料"],["personal","提供身分證、地址或個資"],["download","下載 App、檔案或遠端控制工具"],["other","其他／不確定"]];return `<div class="emergency-card"><p class="step-label">第 1 步</p><h2>對方現在要你做什麼？</h2><p>可複選。只選行為類型，不要輸入真實內容。</p><div class="emergency-options">${options.map(([id,label])=>`<button class="emergency-option ${emergency.answers.requests?.includes(id)?"is-selected":""}" data-emergency-request="${id}" aria-pressed="${emergency.answers.requests?.includes(id)}"><span>${icon(id==="payment"?"chart":id==="otp"?"lock":"shield",23)}</span>${label}</button>`).join("")}</div><button class="button button--primary button--full" data-action="emergency-next" ${!emergency.answers.requests?.length?"disabled":""}>下一步 ${icon("arrow",19)}</button></div>`;}
function emergencyStepTwo(emergency){return `<div class="emergency-card"><p class="step-label">第 2 步</p><h2>你能不能離開這則訊息，從原本的官方管道核對？</h2><p>例如自行開啟原 App、官網、訂單頁、卡片背面電話或原聯絡方式。</p><div class="emergency-choice-grid"><button class="emergency-choice ${emergency.answers.official==="yes"?"is-selected":""}" data-emergency-official="yes" aria-pressed="${emergency.answers.official==="yes"}"><strong>可以</strong><span>我知道原本的官方入口</span></button><button class="emergency-choice ${emergency.answers.official==="unknown"?"is-selected":""}" data-emergency-official="unknown" aria-pressed="${emergency.answers.official==="unknown"}"><strong>不確定</strong><span>我不知道該去哪裡查</span></button><button class="emergency-choice ${emergency.answers.official==="no"?"is-selected":""}" data-emergency-official="no" aria-pressed="${emergency.answers.official==="no"}"><strong>不能</strong><span>對方要求只能照訊息內方式操作</span></button></div><div class="button-row"><button class="button button--ghost" data-action="emergency-back">上一步</button><button class="button button--primary" data-action="emergency-result" ${!emergency.answers.official?"disabled":""}>產生安全下一步</button></div></div>`;}
function emergencyResult(emergency){const requests=emergency.answers.requests??[];const highRisk=requests.some((item)=>["payment","otp","download"].includes(item));const stopItems=[];if(requests.includes("login"))stopItems.push("不要點訊息內連結，也不要在新頁面登入");if(requests.includes("payment"))stopItems.push("不要付款、轉帳或依指示操作 ATM");if(requests.includes("otp"))stopItems.push("不要提供 OTP、密碼、卡片或網銀資料");if(requests.includes("personal"))stopItems.push("不要傳身分證、地址或其他個資");if(requests.includes("download"))stopItems.push("不要下載安裝檔、遠端控制工具或不明 App");if(!stopItems.length)stopItems.push("先暫停回覆與操作，保留訊息但不要轉傳");return `<div class="emergency-result-card"><div class="emergency-result-card__status ${highRisk?"is-danger":"is-caution"}"><span>${icon("siren",29)}</span><div><p>安全優先</p><h2>${highRisk?"先停止高風險操作":"資訊還不完整，先不要急著行動"}</h2></div></div><section><p class="feedback-label">現在先停下</p><ul class="safe-list">${stopItems.map((item)=>`<li>${icon("check",18)}${item}</li>`).join("")}</ul></section><section><p class="feedback-label">改走獨立查證</p><ol class="verification-steps"><li>關閉訊息內連結或通話，不使用對方提供的客服方式。</li><li>自行開啟原 App、官網、訂單頁、卡片背面電話或原聯絡方式。</li><li>若涉及金錢、帳號或個資，可向可信任大人、老師、官方客服或 165 諮詢。</li><li>需要檢舉時保留匿名必要證據，但不要公開個資。</li></ol></section><div class="emergency-warning"><strong>SignalSafe 沒有判定這則訊息一定是真的或假的。</strong><p>它只協助你先降低風險，並改走不受對方控制的查證路徑。</p></div><div class="button-row"><button class="button button--secondary" data-action="restart-emergency">重新檢查</button><button class="button button--primary" data-route="home">完成</button></div></div>`;}
function dataView(){return shell(`<section class="page-heading"><button class="back-button" data-route="home">← 回首頁</button><p>資料與隱私</p><h1>你的紀錄只留在這台裝置。</h1><span>SignalSafe 不建立帳號，也不自動上傳任何練習資料。${state.storageMode==="memory"?"目前為暫時記憶模式，重新整理或關閉頁面可能遺失資料。":""}</span></section><section class="data-layout"><article class="data-summary"><div class="data-summary__icon">${icon("lock",34)}</div><h2>匿名本機資料</h2><dl><div><dt>匿名 ID</dt><dd>${state.anonymousUserId}</dd></div><div><dt>已完成練習</dt><dd>${state.sessions.length} 次</dd></div><div><dt>App 版本</dt><dd>${APP_VERSION}</dd></div><div><dt>題庫版本</dt><dd>${QUESTION_BANK_VERSION}</dd></div></dl></article><div class="data-actions"><article><span>${icon("export",25)}</span><div><h2>匯出完整 JSON</h2><p>包含匿名場次、作答、版本與計時欄位，適合研究備份。</p></div><button class="button button--secondary" data-action="export-json">匯出</button></article><article><span>${icon("chart",25)}</span><div><h2>匯出匿名 CSV</h2><p>每列一題，方便在試算表分析；不含姓名與學校。</p></div><button class="button button--secondary" data-action="export-csv">匯出</button></article><article><span>${icon("export",25)}</span><div><h2>匯入 JSON 備份</h2><p>會取代這台裝置上的現有紀錄。請只匯入可信的 SignalSafe 備份。</p></div><label class="button button--secondary file-button">選擇檔案<input type="file" id="importFile" accept="application/json,.json"></label></article><article class="data-actions__danger"><span>${icon("trash",25)}</span><div><h2>清除全部資料</h2><p>刪除本機練習紀錄、未完成測驗與匿名 ID。此操作無法復原。</p></div><button class="button button--danger" data-action="clear-data">清除</button></article></div></section>`);}
